#include <vector>
#include <algorithm>

void demonstrate_swap_efficiency() {
    std::vector<int> v1(1000000); 
    std::vector<int> v2(1000000); 

    // Assignment: O(N) complexity (slow, copies 1M elements)
    // v1 = v2; 

    // Swap: O(1) complexity (fast, swaps internal pointers)
    std::swap(v1, v2);
}

// Assignment of containers is relatively expensive (Josuttis, p. 133)
